    kind = EXCLUDED.kind, source = EXCLUDED.source, label = EXCLUDED.label,
    geom = EXCLUDED.geom, junction_id = EXCLUDED.junction_id,
    segment_id = EXCLUDED.segment_id, heading_deg = EXCLUDED.heading_deg,
    updated_at = NOW()
WHERE c.kind IS DISTINCT FROM EXCLUDED.kind
   OR c.source IS DISTINCT FROM EXCLUDED.source
   OR c.label IS DISTINCT FROM EXCLUDED.label
   OR NOT ST_OrderingEquals(c.geom, EXCLUDED.geom)
   OR c.junction_id IS DISTINCT FROM EXCLUDED.junction_id
   OR c.segment_id IS DISTINCT FROM EXCLUDED.segment_id
   OR c.heading_deg IS DISTINCT FROM EXCLUDED.heading_deg;

